def reverse_num(num):
    rev_num = 0
    while num > 0:
        rev_num = (rev_num * 10) + (num % 10)
        num = num // 10
    return rev_num

def sort_ascending(lst):
    for i in range(len(lst)):
        for j in range(i+1, len(lst)):
            if lst[i] > lst[j]:
                lst[i], lst[j] = lst[j], lst[i]
    return lst

